        term, coefficient = pending.pop()
        p = 0
        while p + 1 < len(term) and (term[p][0] > term[p + 1][0] or (term[p][0] == term[p + 1][0] and term[p][1] < term[p + 1][1])):
            p += 1
        if p + 1 >= len(term):
            result[term] = result.get(term, 0) + coefficient
