    result = {}
    while pending:
        current, sign = pending.pop()
        position = 0
        while position + 1 < len(current):
            left = current[position]
            right = current[position + 1]
            if left == right:
                break
            if left % 2 < right % 2 or (left % 2 == right % 2 and left > right):
                pending.append((current[:position] + (right, left) + current[position + 2:], -sign))
                if left % 2 == 0 and right == left + 1:
                    pending.append((current[:position] + current[position + 2:], sign))
                break
            position += 1
        if position + 1 >= len(current):
            result[current] = result.get(current, 0) + sign
    return {word: coefficient for word, coefficient in result.items() if coefficient}


def compile_gram(pattern, diagonal):
    product = normal_form(pattern)
    if diagonal:
        return list(product.items())
    result = product.copy()
    for word, coefficient in product.items():
        creators = sum(token % 2 for token in word)
        annihilators = len(word) - creators
        parity = (creators * (creators - 1) // 2 + annihilators * (annihilators - 1) // 2) % 2
