    for i, x in left:
        for j, y in right:
            if i <= j:
                coordinate = (i, j)
            else:
                coordinate = (j, i)
            merged[coordinate] = merged.get(coordinate, 0) + x*y
    return [(coordinate, value) for coordinate, value in merged.items() if value]

